/**
 * docs/CAMPUS_BUILDING_COVERAGE.md — GENERATED by the pipeline from the
 * processed data. Every number below comes from the files of the build that
 * wrote it; nothing is typed by hand. Deterministic: no wall-clock time.
 */
import { getCategory } from '../../src/config/categories.ts';
import type { BuildingsFile, DetectionsFile, Manifest, Place } from '../../src/data/schema.ts';
import type { GoogleSnapshot, MsSnapshot } from './detection-sources.ts';
import type { OutsideRow, QualityReport } from './quality.ts';

export interface CoverageInputs {
  quality: QualityReport;
  manifest: Manifest;
  /** Baseline dataset (scripts/lib/baseline.ts); `ref` says where it came from. */
  previous:
    { schemaVersion?: unknown; datasetVersion?: unknown; counts?: unknown; ref?: unknown } | null | undefined;
  snapshots: { ms: MsSnapshot | null; google: GoogleSnapshot | null };
  places: readonly Place[];
  contextPlaces: readonly Place[];
  buildings: BuildingsFile;
  detections: DetectionsFile;
  osmSourceName: string;
}

export const DIFF_START = '<!-- before-after:start -->';
export const DIFF_END = '<!-- before-after:end -->';

const esc = (s: string) => s.replace(/\|/g, '\\|');
const pct = (f: number | null) => (f === null ? 'n/a' : `${(f * 100).toFixed(2)} %`);
const m2 = (v: number | null) => (v === null ? 'n/a' : `${Math.round(v).toLocaleString('en-US')}`);
const code = (s: string) => `\`${s}\``;

function table(head: string[], rows: string[][]): string[] {
  if (rows.length === 0) return ['_None._', ''];
  return [
    `| ${head.join(' | ')} |`,
    `| ${head.map(() => '---').join(' | ')} |`,
    ...rows.map((r) => `| ${r.join(' | ')} |`),
    '',
  ];
}

/** Keys compared in the before/after diff. */
const DIFF_KEYS = [
  'buildings',
  'buildings:inside',
  'buildings:crossing',
  'buildings:uncertain',
  'buildings:outsideExcluded',
  'buildings:unnamed',
  'places',
  'contextPlaces',
  'detections',
  'boundaryReview:items',
  'directory:keyed',
  'graph:edges',
  'graph:campusEdges',
] as const;

/**
 * Before/after against the BASELINE dataset (by default the one committed at
 * git HEAD — scripts/lib/baseline.ts), so an identical rebuild writes an
 * identical document. The count-change guard outcome is inserted before
 * DIFF_END by insertCountGuard() once validation has run.
 */
function diffSection(i: CoverageInputs): string[] {
  return [DIFF_START, '', ...computedDiff(i), DIFF_END, ''];
}

/** Inserts the count-change guard section (scripts/lib/validate-changes.ts countGuardMarkdown) into the diff block. */
export function insertCountGuard(markdown: string, guardLines: readonly string[]): string {
  const at = markdown.indexOf(DIFF_END);
  if (at < 0) return markdown;
  return [markdown.slice(0, at), ...guardLines, markdown.slice(at)].join('\n').replace(/\n{3,}/g, '\n\n');
}

function computedDiff(i: CoverageInputs): string[] {
  const prevCounts =
    i.previous && typeof i.previous.counts === 'object' && i.previous.counts !== null
      ? (i.previous.counts as Record<string, unknown>)
      : null;
  const out = ['## Before / after this build', ''];
  if (!prevCounts) {
    out.push('No baseline dataset was available, so there is nothing to compare.', '');
    return out;
  }
  const prevVersion = typeof i.previous?.datasetVersion === 'string' ? i.previous.datasetVersion : 'unknown';
  const prevSchema = typeof i.previous?.schemaVersion === 'number' ? i.previous.schemaVersion : 'unknown';
  out.push(
    `Baseline dataset ${code(String(prevVersion))} (schema version ${prevSchema}${typeof i.previous?.ref === 'string' ? `, ${i.previous.ref}` : ''}) → this dataset ${code(i.manifest.datasetVersion)}. ` +
      'A dash means the baseline manifest did not have that count (v1 counted every footprint in the map rectangle as a building).',
    '',
  );
  const rows = DIFF_KEYS.map((k) => {
    const before = prevCounts[k];
    const after = i.manifest.counts[k];
    const b = typeof before === 'number' ? before : null;
    return [
      code(k),
      b === null ? '–' : String(b),
      after === undefined ? '–' : String(after),
      b === null || after === undefined ? '–' : `${after - b >= 0 ? '+' : ''}${after - b}`,
    ];
  });
  out.push(...table(['Count', 'Before', 'After', 'Change'], rows));
  return out;
}

function outsideTable(rows: readonly OutsideRow[]): string[] {
  return table(
    ['OSM id', 'Label', 'Category', 'Area m²', 'Distance to boundary m', 'Kept as context point'],
    rows.map((o) => [
      code(o.id),
      esc(o.displayName),
      o.categoryId,
      m2(o.areaM2),
      o.distanceToBoundaryM === null ? 'n/a' : o.distanceToBoundaryM.toFixed(1),
      o.contextPlace ? 'yes' : 'no',
    ]),
  );
}

export function coverageMarkdown(i: CoverageInputs): string {
  const q = i.quality;
  const m = q.membership;
  const c = i.manifest.counts;
  const inv = i.buildings.features.map((f) => f.properties);
  const lines: string[] = [];
  const ms = q.detections.microsoft;
  const g = q.detections.google;

  lines.push(
    '# Campus building coverage',
    '',
    '<!-- GENERATED by scripts/build-data.ts (scripts/lib/coverage-markdown.ts) — do not edit by hand. -->',
    '',
    `Dataset ${code(i.manifest.datasetVersion)}, built from the ${i.osmSourceName} snapshot retrieved ${q.builtFrom}. ` +
      'Every number on this page is computed from the processed files of that build ' +
      '(`public/data/*`, `data/raw/*`, `data/curated/*`). Nothing here names, numbers or positions a building that the sources do not.',
    '',
    '## Boundary',
    '',
    `- Source: OpenStreetMap ${code(m.boundarySourceRef)} (campus multipolygon), area ${m2(m.boundaryAreaM2)} m².`,
    `- Membership is decided by area fraction inside this polygon with the shared boundary service ` +
      '(`src/geo/boundary.ts`, rules R1–R7 in docs/MODULE_CONTRACTS.md). Area fraction is evidence, not the only criterion: ' +
      'invalid geometry, curated decisions, open boundary-review sections and conflicting tags are applied first.',
    `- Thresholds: inside at ≥ ${m.thresholds.insideMinFraction}, outside at ≤ ${m.thresholds.outsideMaxFraction}; ` +
      `a crossing footprint joins the inventory at ≥ ${m.thresholds.crossingInventoryMinFraction} with no conflicting evidence.`,
    '- Nothing is clipped, discarded silently or moved: a crossing footprint keeps its full outline, and every excluded footprint is listed below.',
    '',
    '## Totals',
    '',
  );
  lines.push(
    ...table(
      ['Measure', 'Count'],
      [
        [
          'Building footprints in the raw OSM snapshot (before any filtering)',
          String(m.footprintsInSnapshot),
        ],
        [
          'Building elements skipped for lack of any usable geometry (listed in the quality report)',
          String(q.skippedFeatures.length),
        ],
        ['Outside the boundary: excluded (never drawn)', String(m.outside.length)],
        [
          '… of which kept only as a point in the opt-in "Nearby, outside campus" layer',
          String(m.outside.filter((o) => o.contextPlace).length),
        ],
        ['Uncertain: held out of the inventory for review', String(m.uncertain.length)],
        ['Crossing the boundary and in the inventory (rule R6)', String(c['buildings:crossing'] ?? 0)],
        ['Inside the boundary and in the inventory', String(c['buildings:inside'] ?? 0)],
        ['Exact duplicates removed (kept one of each pair)', String(q.duplicatesResolved.length)],
        ['**Campus inventory (buildings.geojson)**', `**${c.buildings ?? 0}**`],
        ['Inventory footprint area inside the boundary (m²)', m2(m.insideAreaM2)],
        ['Unnamed inventory buildings', String(c['buildings:unnamed'] ?? 0)],
        ['Unverified detected footprints shipped (detections.geojson)', String(c.detections ?? 0)],
      ],
    ),
  );
  lines.push(...diffSection(i));

  lines.push('## Status by rule', '');
  lines.push(
    ...table(
      ['Status', 'Footprints'],
      Object.entries(m.byStatus).map(([k, v]) => [k, String(v)]),
    ),
  );
  lines.push(
    ...table(
      ['Reason code', 'Footprints'],
      Object.entries(m.byReason).map(([k, v]) => [code(k), String(v)]),
    ),
  );

  lines.push('## Crossing the boundary, in the inventory', '');
  lines.push(
    ...table(
      ['OSM id', 'Label', 'Inside fraction', 'Area m²', 'Inside m²'],
      m.crossing.map((r) => [
        code(r.id),
        esc(r.displayName),
        pct(r.insideFraction),
        m2(r.areaM2),
        m2(r.insideAreaM2),
      ]),
    ),
  );
  lines.push(
    '## Uncertain: held for review (not in the inventory)',
    '',
    'Listed in `public/data/boundary-review.json` for the admin data-quality view. Each stays out of the campus inventory ' +
      'until a dated decision is added to `data/curated/boundary-review.json` (owner confirmation, official publication, ' +
      'physical survey or an OSM boundary fix). No decision is pre-filled.',
    '',
  );
  lines.push(
    ...table(
      ['OSM id', 'Label', 'Inside fraction', 'Distance m', 'Rule', 'Section'],
      m.uncertain.map((r) => [
        code(r.id),
        esc(r.displayName),
        pct(r.insideFraction),
        r.distanceToBoundaryM === null ? 'n/a' : r.distanceToBoundaryM.toFixed(1),
        code(r.reasonCode),
        r.reviewSectionId ? code(r.reviewSectionId) : '–',
      ]),
    ),
  );
  if (m.placeReviewItems.length > 0) {
    lines.push('Places (not footprints) held for review in an open section:', '');
    lines.push(
      ...table(
        ['Place id', 'Label', 'Section'],
        m.placeReviewItems.map((p) => [
          code(p.id),
          esc(p.displayName),
          p.reviewSectionId ? code(p.reviewSectionId) : '–',
        ]),
      ),
    );
  }
  lines.push('### Boundary-review sections', '');
  lines.push(
    ...table(
      ['Section', 'Title', 'Status', 'Buffer m', 'Affected'],
      m.sections.map((s) => [
        code(s.id),
        esc(s.title),
        s.status,
        String(s.bufferM),
        s.affected.map(code).join(', ') || '–',
      ]),
    ),
  );
  lines.push(
    `Curated decisions: ${m.decisions.length}${m.decisions.length ? ` (${m.decisions.map((d) => `${code(d.featureId)} → ${d.status}, ${d.decidedAt}`).join('; ')})` : ''}.`,
    '',
  );
  if (m.pointAreaDisagreements.length > 0)
    lines.push(
      `Point-on-surface or centroid tests disagree with the area fraction for ${m.pointAreaDisagreements.length} footprint(s): ` +
        `${m.pointAreaDisagreements.map(code).join(', ')}. Recorded, status unchanged (rule R7).`,
      '',
    );

  lines.push(
    '## Outside the boundary: excluded',
    '',
    `${m.outside.length} footprints lie outside the campus boundary. None is drawn in any view. They stay in the raw snapshot (` +
      '`data/raw/osm/`).',
    '',
  );
  lines.push(
    ...table(
      ['Distance to boundary', 'Footprints'],
      Object.entries(m.outsideByDistance).map(([k, v]) => [k, String(v)]),
    ),
  );
  if (m.nearBoundaryExclusions.length > 0)
    lines.push(
      `${m.nearBoundaryExclusions.length} of them lie within 10 m of the boundary and are not in any review section: ` +
        `${m.nearBoundaryExclusions.map(code).join(', ')}. If any may be campus land, add a section to ` +
        '`data/curated/boundary-review.json` with its evidence.',
      '',
    );
  lines.push('<details><summary>All outside footprints, nearest first</summary>', '');
  lines.push(...outsideTable(m.outside));
  lines.push('</details>', '');

  lines.push('## Duplicates, overlaps and stacked parts', '');
  lines.push(
    ...table(
      ['Kept', 'Removed', 'IoU', 'Rule'],
      q.duplicatesResolved.map((d) => [code(d.kept), code(d.dropped), String(d.iou), esc(d.rule)]),
    ),
  );
  lines.push(
    ...table(
      ['Footprint A', 'Footprint B', 'Overlap m²', 'IoU', 'Share of smaller', 'Kind'],
      q.overlaps.map((o) => [
        code(o.a),
        code(o.b),
        String(o.intersectionM2),
        String(o.iou),
        String(o.smallerCovered),
        o.kind,
      ]),
    ),
  );
  lines.push(
    'Overlaps and contained parts are reported only; OSM should map them as `building:part` with `min_level`.',
    '',
  );

  lines.push('## Recovered candidates: unverified detected footprints', '');
  if (!ms.used && !g.used) lines.push('No detection snapshot is committed, so no candidates are shown.', '');
  else {
    lines.push(
      'Machine detections that no OSM footprint matches. They are shown only in the opt-in, flat, dashed ' +
        '"Unverified detected footprints" layer: never extruded, named, numbered, searched, routed or counted as campus buildings. ' +
        'Geometry is exactly as published; the documented ~5.6 m Microsoft–OSM offset (docs/CAMPUS_GEOGRAPHY_AUDIT.md §5.1) is not corrected, ' +
        'because there is no evidence which source is right.',
      '',
    );
    lines.push(
      ...table(
        ['Measure', 'Count'],
        [
          ['Microsoft footprints in the snapshot (map extent)', String(ms.inSnapshot)],
          ['… invalid polygons skipped', String(ms.invalid)],
          ['… ≥ 50 % inside the boundary', String(ms.candidates)],
          ['… matched to an OSM footprint (IoU ≥ 0.3 or ≥ 50 % covered): not shown', String(ms.matched)],
          ['… partly covered by OSM (10–50 %): shown', String(ms.partial)],
          ['… not covered by OSM (< 10 %): shown', String(ms.msOnly)],
          ['**Microsoft detections shipped**', `**${ms.shipped}**`],
          [
            `… confirmed by a Google Open Buildings point (confidence ≥ ${g.threshold ?? 'n/a'})`,
            String(ms.confirmedByGoogle),
          ],
          ['Google Open Buildings points in the snapshot (map extent)', String(g.inSnapshot)],
          ['… inside the boundary', String(g.inBoundary)],
          [`… inside the boundary with confidence ≥ ${g.threshold ?? 'n/a'}`, String(g.strongInBoundary)],
          [
            `**Google-only point detections shipped** (area ≥ ${g.minAreaM2 ?? 'n/a'} m², in no OSM or Microsoft footprint)`,
            `**${g.shipped}**`,
          ],
          ['Total area of shipped Microsoft detections (m²)', m2(q.detections.shippedAreaM2)],
        ],
      ),
    );
  }

  lines.push('## Coverage by category', '');
  const catCount = new Map<string, number>();
  for (const p of inv) catCount.set(p.categoryId, (catCount.get(p.categoryId) ?? 0) + 1);
  lines.push(
    ...table(
      ['Category (inventory buildings)', 'Buildings'],
      [...catCount.entries()]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => [esc(getCategory(k).label), String(v)]),
    ),
  );
  lines.push(
    ...table(
      ['Important category', 'Campus places', 'Nearby outside (context layer only)', 'Status'],
      q.importantCategories.map((x) => [esc(x.label), String(x.total), String(x.nearbyOutside), x.status]),
    ),
  );

  lines.push(
    '## Coverage grid',
    '',
    `Map-key grid cells (200 m, origin ${code('APP_CONFIG.directory.gridOrigin')}): inventory buildings and Microsoft detections by anchor. ` +
      'A cell with large detection area and little inventory area is a mapping gap to survey.',
    '',
  );
  lines.push(
    ...table(
      ['Cell', 'Inventory buildings', 'Inventory area m²', 'Detections', 'Detection area m²'],
      q.coverageGrid.map((x) => [
        x.cell,
        String(x.inventoryBuildings),
        m2(x.inventoryAreaM2),
        String(x.detections),
        m2(x.detectionAreaM2),
      ]),
    ),
  );

  // --- specific structures: what the sources contain, and what evidence is needed
  const nameHit = (re: RegExp) => (p: Place) => re.test(p.name ?? '') || p.aliases.some((a) => re.test(a));
  const agri = i.places.filter(nameHit(/agri/i));
  const hostels = i.places.filter((p) => p.categoryId === 'hostel');
  const hostelsOutside = i.contextPlaces.filter((p) => p.categoryId === 'hostel');
  const food = i.places.filter((p) => p.categoryId === 'food');
  const small = inv.filter((p) => p.areaM2 !== null && p.areaM2 < 20);
  const unnamedSmall = inv.filter(
    (p) => p.name === null && p.areaM2 !== null && p.areaM2 >= 20 && p.areaM2 < 100,
  );
  const detBands: Array<[string, number, number]> = [
    ['under 25 m²', 0, 25],
    ['25–100 m²', 25, 100],
    ['100–300 m²', 100, 300],
    ['300–1,000 m²', 300, 1000],
    ['1,000 m² or more', 1000, Infinity],
  ];
  const msDet = i.detections.features
    .filter((f) => f.properties.source === 'microsoft-ml')
    .map((f) => f.properties.areaM2);
  const placeList = (ps: readonly Place[]) =>
    ps.length === 0
      ? 'none'
      : ps
          .map((p) => `${code(p.id)} ${esc(p.displayName)} (${p.kind}${p.location ? '' : ', no position'})`)
          .join('; ');

  lines.push(
    '## Specific structures: what the sources contain',
    '',
    'These are **review items**, never facilities: nothing below is turned into a place, a name or a block number. ' +
      "The campus illustration's index is an unverified lead list only (docs/GEODATA_SOURCES_AND_LICENSES.md §14); its numbers are never used as building names or block numbers. They appear only on the owner-supplied illustration itself (the Illustrated overview), marked as not official.",
    '',
    '### Agriculture Block',
    '',
    `- Campus places whose name or alias mentions agriculture: ${placeList(agri)}.`,
    '- No OSM footprint in the inventory is named or tagged as agriculture. Status: **no identified footprint**.',
    '- Evidence needed: a surveyed or officially published position tied to one footprint (then an OSM `name`/`ref`, or a curated alias with a citation).',
    '',
    '### Hostels',
    '',
    `- Campus places in the hostel category: ${placeList(hostels)}.`,
    `- Off-campus places tagged as hostels (private accommodation, shown only in the opt-in context layer, never as campus hostels): ${hostelsOutside.length}.`,
    `- Inventory buildings with ${code('building=dormitory')} or a hostel tag: ${inv.filter((p) => p.categoryId === 'hostel').length}. Status: **${hostels.length === 0 ? 'no identified footprint' : 'see list'}**.`,
    '- Evidence needed: survey of names and entrances, mapped in OSM as `building=dormitory` + `name` + `ref`.',
    '',
    '### Canteens and kiosks',
    '',
    `- Campus places in the food category: ${placeList(food)}.`,
    '- Small detections could be kiosks or sheds; their use cannot be inferred from a footprint.',
    '- Evidence needed: site visit (name, position, opening hours), mapped in OSM as `amenity=cafe|fast_food|food_court|restaurant`.',
    '',
    '### Small academic and ancillary structures',
    '',
    `- Inventory footprints under 20 m² (no map key unless named or hosting a facility): ${small.length}.`,
    `- Unnamed inventory footprints of 20–100 m²: ${unnamedSmall.length}.`,
    `- Shipped Microsoft detections by size: ${detBands.map(([label, lo, hi]) => `${label} ${msDet.filter((a) => a >= lo && a < hi).length}`).join(', ')}.`,
    '- Status: **unidentified**. Evidence needed: imagery check in iD/JOSM and a site visit; trace real structures into OSM.',
    '',
    '## Names and locations awaiting verification',
    '',
    `- Unnamed inventory buildings: ${c['buildings:unnamed'] ?? 0} (titles use the map key, never an invented name).`,
    `- Campus places without a map position (listed by a source, not located): ${q.placesWithoutLocation.length}.`,
    `- Places by verification status: ${Object.entries(q.verification.byStatus)
      .map(([k, v]) => `${k} ${v}`)
      .join(', ')}.`,
    `- Official block labels: ${inv.filter((p) => p.officialBlockLabel !== null).length} (no cited source ties a block number to a footprint).`,
    `- Map keys: ${q.directory.keyed} of ${q.directory.eligible} eligible buildings keyed; unkeyed ${q.directory.unkeyed.length}${q.directory.unkeyed.length ? ` (${q.directory.unkeyed.map(code).join(', ')}; run \`npm run data:keys\`)` : ''}.`,
    '',
    '## Sources and licences',
    '',
  );
  const sourceRows: string[][] = i.manifest.sources.map((s) => [
    code(s.id),
    esc(s.name),
    esc(s.license ?? 'cited source (see manifest)'),
    s.licenseTextPath ? code(s.licenseTextPath) : '–',
  ]);
  lines.push(...table(['Source id', 'Name', 'Licence', 'Licence text shipped'], sourceRows));
  lines.push(
    '- Footprints, names, levels, places, paths and the boundary: OpenStreetMap (ODbL 1.0). `public/data` is a derived database under ODbL 1.0.',
    i.snapshots.ms
      ? `- Unverified detections: Microsoft Global ML Building Footprints, quadkey ${i.snapshots.ms.source.quadkey}, release ${i.snapshots.ms.source.release}, CDLA Permissive 2.0 (licence text shipped).`
      : '- Microsoft Global ML Building Footprints: not used in this build.',
    i.snapshots.google
      ? `- Detection confirmations and Google-only points: Google Open Buildings ${i.snapshots.google.source.version}, S2 cell ${i.snapshots.google.source.s2Token}, used under ODbL 1.0 (dual-licensed CC BY 4.0 / ODbL 1.0).`
      : '- Google Open Buildings: not used in this build.',
    '- Curated records cite their own sources (`data/curated/`).',
    '',
  );
  return `${lines
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trimEnd()}\n`;
}
